<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#673ab7"><title>Sign in · BantayGamit</title><link rel="icon" href="<?= base_url('favicon.ico') ?>"><link rel="stylesheet" href="<?= base_url('assets/css/app.css') ?>"></head><body class="auth-page"><main class="auth-wrap"><section class="auth-card"><img class="auth-logo" src="<?= base_url('assets/img/logo.png') ?>" alt="BantayGamit logo"><div class="auth-title"><h1>Welcome to BantayGamit</h1><p>Web-Based Barangay Equipment Monitoring System</p></div><?php if($m=session()->getFlashdata('error')): ?><div class="alert danger" role="alert"><?= esc($m) ?></div><?php endif; ?><?php if($errors=session()->getFlashdata('errors')): ?><div class="alert danger"><ul><?php foreach((array)$errors as $e): ?><li><?= esc($e) ?></li><?php endforeach; ?></ul></div><?php endif; ?><form method="post" action="<?= site_url('login') ?>" class="stack-form"><?= csrf_field() ?><label>Username<input type="text" name="username" value="<?= esc(old('username')) ?>" autocomplete="username" required autofocus></label><label>Password<span class="password-field"><input id="login-password" type="password" name="password" autocomplete="current-password" required><button type="button" data-password-toggle="login-password" aria-label="Show password"><?= ui_icon('eye') ?></button></span></label><button class="btn primary wide" type="submit"><?= ui_icon('log-in') ?> Sign In</button></form></section><p class="auth-footer">Secure barangay equipment access for authorized users.</p></main><script src="<?= base_url('assets/js/app.js') ?>"></script></body></html>
